MQL:
db.airlines.aggregate([
  { $unwind: { path: "$flights", preserveNullAndEmptyArrays: false } },
  { $setWindowFields: {
      partitionBy: { Airline: "$Abbreviation", route: { $concat: ["$flights.SourceAirport", "-", "$flights.DestAirport"] } },
      sortBy: { "flights.FlightNo": 1 },
      output: {
        route_density: {
          $sum: 1,
          window: { documents: [-2, 0] }
        }
      }
  } },
  { $group: {
      _id: "$_id",
      Abbreviation: { $first: { $ifNull: ["$Abbreviation", "(unknown)"] } },
      route_densities: { $push: "$route_density" }
  } },
  { $project: {
      Abbreviation: 1,
      route_densities: 1,
      median_density: { $arrayElemAt: [
        { $sortArray: { input: "$route_densities", sortBy: 1 } },
        { $floor: { $divide: [ { $size: "$route_densities" }, 2 ] } }
      ] }
  } },
  { $facet: {
      per_airline: [
        { $project: {
            Abbreviation: 1,
            max_route_density: { $max: {
              $filter: {
                input: "$route_densities",
                as: "d",
                cond: { $gt: ["$$d", "$median_density"] }
              }
            } }
        } },
        { $match: { max_route_density: { $ne: null } } }
      ]
  } },
  { $unwind: "$per_airline" },
  { $replaceRoot: { newRoot: "$per_airline" } },
  { $project: { _id: 0, Abbreviation: 1, max_route_density: 1 } }
])
